def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1
    chars = list(dict.fromkeys(alphabet))
    k = len(chars)
    mp = {c: i for i, c in enumerate(chars)}
    nxt = [[-1] * k]
    term = [False]

    def add_node() -> int:
        nxt.append([-1] * k)
        term.append(False)
        return len(nxt) - 1

    for w in banned:
        if not w:
            continue
        u = 0
        ok = True
        for ch in w:
            c = mp.get(ch)
            if c is None:
                ok = False
                break
            if nxt[u][c] < 0:
                nxt[u][c] = add_node()
            u = nxt[u][c]
        if ok:
            term[u] = True

    m = len(nxt)
    fail = [0] * m
    from collections import deque
    q = deque()
    for c in range(k):
        v = nxt[0][c]
        if v < 0:
            nxt[0][c] = 0
        else:
            q.append(v)
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        fu = fail[u]
        for c in range(k):
            v = nxt[u][c]
            if v < 0:
                nxt[u][c] = nxt[fu][c]
            else:
                fail[v] = nxt[fu][c]
                q.append(v)

    bad = [False] * m
    for u in order:
        bad[u] = term[u] or bad[fail[u]]

    safe = [i for i in range(m) if not bad[i]]
    index = {s: i for i, s in enumerate(safe)}
    sN = len(safe)
    T = [[0] * sN for _ in range(sN)]
    for u in safe:
        ui = index[u]
        row = T[ui]
        for c in range(k):
            v = nxt[u][c]
            if not bad[v]:
                row[index[v]] += 1

    def mul(A, B):
        n_ = len(A)
        C = [[0] * n_ for _ in range(n_)]
        for i in range(n_):
            Ai = A[i]
            Ci = C[i]
            for t in range(n_):
                a = Ai[t]
                if a:
                    Bt = B[t]
                    for j in range(n_):
                        Ci[j] = (Ci[j] + a * Bt[j]) % MOD
        return C

    def mpow(A, e):
        n_ = len(A)
        R = [[0] * n_ for _ in range(n_)]
        for i in range(n_):
            R[i][i] = 1
        while e:
            if e & 1:
                R = mul(R, A)
            A = mul(A, A)
            e >>= 1
        return R

    Tn = mpow(T, n)
    return sum(Tn[index[0]]) % MOD
